-- ============================================================================
--  جمعية حاضنة الجمعيات — تحميل محتوى الموقع الحالي إلى قاعدة البيانات
--
--  مولَّد آليًّا من src/data/*.json بواسطة src/gen_seed.py — لا تُعدّله يدويًّا.
--  شغّله بعد schema.sql و schema-v2.sql و schema-v3.sql.
--  آمن للتشغيل أكثر من مرة (upsert على مفاتيح طبيعية).
-- ============================================================================

-- ----------------------------------------------------------------------
--  الأشخاص: الجمعية العمومية + مجلس الإدارة + فريق العمل
-- ----------------------------------------------------------------------
on conflict (seed_key) do update set
  title=excluded.title, role=excluded.role, rank=excluded.rank,
  cat=excluded.cat, phone=excluded.phone, email=excluded.email,
  photo=excluded.photo, sort=excluded.sort;

--  تنبيه: أسماء متكرّرة في ملف البيانات — أُدرجت كلها كأشخاص مستقلّين.
--  إن كان أحدها تكرارًا سهوًا فاحذفه من اللوحة بعد التحميل:
--    assembly: عبدالرحمن محمد الجمعة  (2 مرّة)

-- ----------------------------------------------------------------------
--  شعارات الشركاء
-- ----------------------------------------------------------------------
on conflict (name) do update set
  logo=excluded.logo, url=excluded.url, sort=excluded.sort;

-- ----------------------------------------------------------------------
--  الأخبار
-- ----------------------------------------------------------------------
on conflict (date, title) do update set
  tag=excluded.tag, lead=excluded.lead, body=excluded.body, facts=excluded.facts,
  cta_label=excluded.cta_label, cta_url=excluded.cta_url, image=excluded.image;

-- ----------------------------------------------------------------------
--  الوثائق (السجلّات فقط — الملفات نفسها تبقى في site/files/)
-- ----------------------------------------------------------------------
-- ملاحظة: storage_path هنا مسار الملف داخل الموقع، لا مسار مستودع Supabase،
-- لأنّ هذه الملفات مرفوعة مع الموقع أصلًا وتعمل روابطها. ما يُرفع من اللوحة
-- لاحقًا يُخزَّن في المستودع ويأخذ مسارًا يبدأ بالتصنيف.
on conflict (storage_path) do update set
  category=excluded.category, title=excluded.title, dl_name=excluded.dl_name,
  doc_date=excluded.doc_date, size_label=excluded.size_label, pages=excluded.pages;

-- ----------------------------------------------------------------------
--  إعلان أن القاعدة هي مصدر القوائم
-- ----------------------------------------------------------------------
-- بهذا الإعداد تُفرَّغ القائمة على الموقع فعلًا إذا أخفى المدير كل صفوفها،
-- بدل أن يظهر المحذوف من البناء الثابت. لا تُشغّله قبل تحميل الصفوف أعلاه.
   'القوائم (الأعضاء والشركاء) مصدرها قاعدة البيانات لا ملفات البناء', true)
on conflict (key) do update set value = excluded.value;

-- ----------------------------------------------------------------------
--  تحقّق
-- ----------------------------------------------------------------------
select 'people' as t, count(*) from public.people
union all select 'partners', count(*) from public.partners
union all select 'news', count(*) from public.news
union all select 'documents', count(*) from public.documents;
