insert into public.news (date,tag,title,lead,body,facts,cta_label,cta_url,image,status) values
  ('2026-06-22','تدريب','تدريب المدربين (TOT)','مسار تدريبي حضوري يحوّل التدريب من نقلٍ للمعرفة إلى صناعةٍ للأثر.','{"أطلقت حاضنة الجمعيات دورة «تدريب المدربين (TOT): تأهيل الكوادر» ضمن مسارات النسخة الثانية من برنامج نواة، وهي مسار احترافي يضع بين يدي المشارك أدوات التقييم الدقيق، ومعايير التصميم التدريبي المتقدم، واستراتيجيات التأثير الفعّال.","يستهدف المسار مسؤولي التدريب وبناء القدرات في القطاع غير الربحي، والمدربين والمستشارين العاملين في المنظمات الأهلية، والقيادات ومديري الإدارات في مجالات التدريب والمعرفة."}','[{"label": "المدرب", "value": "د. أحمد عطا الله الرفاعي"}, {"label": "المدة", "value": "5 أيام حضورية + يوم عن بُعد"}, {"label": "التاريخ", "value": "5 - 9 يوليو 2026م (الأحد إلى الخميس)"}, {"label": "الوقت", "value": "4:30 - 10:00 مساءً"}, {"label": "المكان", "value": "القصيم - بريدة"}, {"label": "الشهادة", "value": "معتمدة (بعد اجتياز التقييم)"}]'::jsonb,'سجّل اهتمامك','https://offf.to/J45V','news-20260622-01.jpg','published'),
  ('2026-06-24','برامج','انطلاق «برنامج وارف»','من عمق الرسالة التنموية إلى استدامة الأثر المؤسسي الراسخ.','{"يسرّ حاضنة الجمعيات أن تفتح آفاق التمكين عبر برنامج وارف؛ وهو تجربة احتضان مؤسسي متكاملة صُممت خصيصًا لمرافقة الجمعيات الأهلية الناشئة في رحلتها نحو النضج والتطوير، تلبيةً لمستهدفات القطاع غير الربحي في بناء كيانات متينة ومستدامة.","يرافق البرنامج الجمعيات بدءًا من تشخيص الواقع وتحليل الاحتياج، وصولًا إلى بناء الأسس المؤسسية التي تعزّز الجاهزية وتحقيق الأثر، عبر أربعة مسارات: التحليل المؤسسي، والخريطة الاستراتيجية، وتنمية الموارد المالية، وبيئة عمل مرنة.","ويشترط البرنامج في شركاء الأثر ثلاثة معايير: الامتثال النظامي بترخيص رسمي ساري، والاستقرار القيادي بمجلس إدارة مكتمل نظامًا مع إدارة تنفيذية متفرّغة، والجدية والجاهزية بالاستعداد الكامل من قِبل المنظمة لبدء المسار."}','[{"label": "المقاعد", "value": "محدودة"}]'::jsonb,'سجّل اهتمامك','https://offf.to/d4Od','news-20260624-02.jpg','published'),
  ('2026-07-05','تدريب','القيادة الاستراتيجية للقيادات النسائية','لتمكين الكفاءات النسائية في القطاع غير الربحي وصناعة الأثر المستدام.','{"تنظّم حاضنة الجمعيات دورة تدريبية مخصّصة للقيادات النسائية تتناول مفاهيم القيادة الحديثة والنسائية الفاعلة، وأدوات التفكير الاستراتيجي وصناعة القرار، والذكاء العاطفي وقيادة فرق العمل، وإدارة التغيير وتحقيق التحول المؤسسي.","تستهدف الدورة عضوات مجالس الإدارة والقيادات التنفيذية، ومديرات الإدارات ورئيسات الأقسام، والمرشحات للمناصب القيادية في القطاع غير الربحي."}','[{"label": "المدرّبة", "value": "أ.د. نورة بنت محمد البليهد"}, {"label": "المدة", "value": "3 أيام تدريبية"}, {"label": "التاريخ", "value": "13 - 15 يوليو 2026م"}, {"label": "الوقت", "value": "7:30 - 10:30 مساءً"}, {"label": "المكان", "value": "افتراضي (عن بُعد)"}, {"label": "الشهادة", "value": "معتمدة"}]'::jsonb,'سجّلي اهتمامكِ','https://offf.to/Ed3f','news-20260705-03.jpg','published'),
  ('2026-07-12','تدريب','حوكمة المنظمات غير الربحية','نحو امتثال تنظيمي وشفافية مؤسسية مستدامة.','{"لأن حوكمة المنظمات هي حجر الزاوية لضمان استدامة الأثر، تقدّم حاضنة الجمعيات ضمن مسارات برنامج نواة مسارًا تخصصيًا عبر دورة حوكمة المنظمات غير الربحية.","تجربة معرفية رصينة تُكسب قيادات القطاع غير الربحي أدوات تطبيق مؤشرات الامتثال والشفافية، ومنهجيات إدارة المخاطر التشغيلية والقانونية، وآليات الارتقاء بكفاءة الأداء المؤسسي لتعزيز ثقة المانحين، مع الوقوف على أبرز التحديثات التشريعية وأبرز المخالفات المتكررة.","تستهدف الدورة أعضاء مجالس الإدارات والقيادات التنفيذية، ومسؤولي الحوكمة والمراجعة والالتزام، ومديري الإدارات المالية والإدارية."}','[{"label": "المدرب", "value": "أ. إبراهيم صالح الغرير"}, {"label": "المدة", "value": "يوم تدريبي واحد"}, {"label": "التاريخ", "value": "20 يوليو 2026م"}, {"label": "الوقت", "value": "7:30 - 10:30 مساءً"}, {"label": "المكان", "value": "افتراضي (عن بُعد)"}, {"label": "الشهادة", "value": "معتمدة · الدورة مجانية"}]'::jsonb,'سجّل الآن','https://offf.to/Y55D','news-20260712-04.jpg','published'),
  ('2026-07-15','إنجازات','تخريج الدفعة الأولى من «وارف»','من جذور التمكين.. إلى وارف الأثر.','{"انطلاقًا من دور حاضنة الجمعيات كرافدٍ للبناء المؤسسي، تعتزّ الجمعية بتخريج الدفعة الأولى من الكيانات الأهلية ضمن النسخة الأولى لبرنامج وارف، بعد رحلة احتضان نوعية أثمرت عن تصميم هياكل تنظيمية راسخة، وهندسة توجهات استراتيجية، ونماذج عمل ابتكارية.","رحلة احتضان مؤسسي رافقت فيها الجمعية الكيانات الأهلية لترسيخ البناء الداخلي وتعميق الأثر، وأثمرت عن تشخيص التحديات وتحليل الاحتياجات، وصياغة الرؤى وإعداد الخطط الاستراتيجية والتشغيلية، وبناء وتطوير نماذج العمل الابتكارية، وتطوير الهياكل التنظيمية لتعزيز الجاهزية المؤسسية.","الجمعيات الخريجة: جمعية العناية بالمسلمين الجدد، وجمعية استزراع شجر الأراك (SiwakGrow)، وجمعية فجر للعناية بالمساجد، وجمعية تواصل للعمل العائلي التنموي، والهادي لحفظ النعمة.","وتثمّن حاضنة الجمعيات الدور الريادي للرعاة وشركاء التمكين: أوقاف الضحيان، ومؤسسة والدة بدر بن صالح الراجحي وأولادها الأهلية، ومجلس الجمعيات الأهلية بالقصيم، وصندوق دعم الجمعيات."}','[]'::jsonb,null,null,'news-20260715-05.jpg','published'),
  ('2026-07-19','تدريب','بناء التوجّه الاستراتيجي','نحو رؤية واضحة وأثر مؤسسي مستدام.','{"لأن التوجّه الاستراتيجي الواضح هو بوصلة المنظمة لضمان استدامة الأثر، تقدّم حاضنة الجمعيات ضمن مسارات النسخة الثانية من برنامج نواة مسارًا تخصصيًا عبر دورة بناء التوجّه الاستراتيجي.","تجربة معرفية رصينة تُكسب قيادات القطاع غير الربحي أدوات صياغة الرؤية والرسالة والأهداف بواقعية، ومنهجيات تحليل البيئة المؤسسية الداخلية والخارجية وتصميم مؤشرات الأداء، وآليات بناء خارطة طريق فعّالة لتعزيز كفاءة التخطيط الاستراتيجي.","تستهدف الدورة أعضاء مجالس الإدارة في الجمعيات الناشئة، والقيادات التنفيذية في القطاع غير الربحي، والمختصين والمهتمين بالتطوير والتخطيط المؤسسي."}','[{"label": "المدرب", "value": "م. محمد بن خالد السيف"}, {"label": "المدة", "value": "يومان تدريبيان"}, {"label": "التاريخ", "value": "27 - 28 يوليو 2026م"}, {"label": "الوقت", "value": "7:30 - 10:30 مساءً"}, {"label": "المكان", "value": "افتراضي (عن بُعد)"}, {"label": "الشهادة", "value": "معتمدة"}]'::jsonb,'سجّل الآن','https://offf.to/cMcn','news-20260719-06.jpg','published'),
  ('2026-07-20','إنجازات','تخريج «جمعية بليغ» ضمن «نشأة»','من التأسيس.. إلى الأثر المستدام.','{"لأن المعرفة هي حجر الزاوية في نهضة المجتمعات، ومن استدامة المبادرات التعليمية والبحثية تُبنى ركائز المستقبل؛ تبارك حاضنة الجمعيات تخريج جمعية بليغ — الجمعية التاسعة عشرة — كإنجاز جديد ضمن ثمرات برنامج نشأة.","جاء التخريج بعد استكمال مراحل التأسيس المؤسسي وفق اللوائح النظامية للمركز الوطني لتنمية القطاع غير الربحي، لتنطلق الجمعية بكيان مؤسسي متين نحو الريادة في تقديم ودعم الخدمات التعليمية والبحثية، وتعزيز المبادرات المعرفية، وبناء قدرات المجتمع وترسيخ أثر تعليمي مستدام."}','[]'::jsonb,null,null,'news-20260720-07.jpg','published'),
  ('2026-07-22','إنجازات','تخريج الدفعة الثانية من «وارف»','تتجدد الثمار.. وتورق غِراس التمكين.','{"بخطى طموحة وعزيمة راسخة، تعتزّ حاضنة الجمعيات بتخريج الدفعة الثانية من الكيانات الأهلية ضمن برنامج وارف؛ في رحلة تحوّل مؤسسي تشاركية أثمرت عن مسارات استراتيجية وهياكل متينة لتكون ظلالًا وارفة في ميدان العمل التنموي.","الجمعيات الخريجة: سنا النسائية للتطوير والتنمية، وجمعية المعلمين، وجمعية العناية بالمساجد بالحيسونية، وجمعية الطيف للدعم الديني والروحي لمرضى الطب التلطيفي، وجمعية اقتصاديات الأسرة.","وتبارك الجمعية لشركاء الأثر انطلاقتهم، وتثمّن الدور الريادي للرعاة والداعمين في تحقيق مستهدفات التنمية المستدامة."}','[]'::jsonb,null,null,'news-20260722-08.jpg','published'),
  ('2026-07-26','تدريب','بناء الشراكات مع القطاع الخاص','نحو شراكات فاعلة وقيمة مؤسسية مستدامة.','{"ضمن مسارات برنامج نواة، تقدّم حاضنة الجمعيات الدورة التدريبية «بناء الشراكات بين الجمعيات والقطاع الخاص في مجال المسؤولية الاجتماعية»، لتمكين المنظمات من التحول نحو «عرض القيمة» وإبرام الاتفاقيات النوعية.","تتناول الدورة التخطيط الاستراتيجي وتحديد القيمة المضافة واختيار الشريك المناسب، وبناء قنوات التواصل والوصول لصاحب القرار، وتصميم عروض الشراكة وتقديمها باحترافية، وإتمام الشراكة وإدارة استمراريتها وتجديدها.","تستهدف الدورة العاملين في إدارات المسؤولية الاجتماعية والشراكات بالجمعيات، والمسؤولين عن التسويق والتواصل المؤسسي، ومديري ومنسقي المشاريع المعنيين بتطوير مصادر التمويل."}','[{"label": "المدرب", "value": "د. فهد بن علي العليان"}, {"label": "المدة", "value": "يومان تدريبيان"}, {"label": "التاريخ", "value": "3 - 4 أغسطس 2026م"}, {"label": "الوقت", "value": "7:30 - 10:00 مساءً"}, {"label": "المكان", "value": "افتراضي (عن بُعد)"}, {"label": "الشهادة", "value": "معتمدة"}]'::jsonb,'سجّل الآن','https://offf.to/tnj3','news-20260726-09.jpg','published')
